package main

import (
	"fmt"
	"io"

	"github.com/mezzato/revpi/pkg/gopicontrol"
)

type variableInfo struct {
	offset uint32
	bits   uint16
}

type processImage interface {
	Variable(name string) (variableInfo, error)
	Read(offset uint32, destination []byte) (int, error)
	Write(offset uint32, source []byte) (int, error)
	Close() error
}

type goPiControlImage struct {
	control *gopicontrol.RevPiControl
}

func newGoPiControlImage() *goPiControlImage {
	return &goPiControlImage{control: gopicontrol.NewRevPiControl()}
}

func (g *goPiControlImage) Variable(name string) (variableInfo, error) {
	variable, err := g.control.GetVariableInfo(name)
	if err != nil {
		return variableInfo{}, err
	}
	return variableInfo{offset: uint32(variable.I16uAddress), bits: variable.I16uLength}, nil
}

func (g *goPiControlImage) Read(offset uint32, destination []byte) (int, error) {
	return g.control.Read(offset, destination)
}

func (g *goPiControlImage) Write(offset uint32, source []byte) (int, error) {
	return g.control.Write(offset, source)
}

func (g *goPiControlImage) Close() error { return g.control.Close() }

type ledDevice struct {
	image  processImage
	offset uint32
	led    string
}

func newLEDDevice(image processImage, led string) (*ledDevice, error) {
	variable, err := image.Variable("RevPiLED")
	if err != nil {
		return nil, fmt.Errorf("find RevPiLED: %w", err)
	}
	if variable.bits != 8 {
		return nil, fmt.Errorf("RevPiLED has unexpected width %d bits, want 8", variable.bits)
	}
	if _, err := mergeLEDColor(0, led, colorOff); err != nil {
		return nil, err
	}
	return &ledDevice{image: image, offset: variable.offset, led: led}, nil
}

func (d *ledDevice) SetColor(color ledColor) error {
	current := []byte{0}
	read, err := d.image.Read(d.offset, current)
	if err != nil {
		return fmt.Errorf("read RevPiLED: %w", err)
	}
	if read != len(current) {
		return fmt.Errorf("read RevPiLED: %w", io.ErrUnexpectedEOF)
	}
	next, err := mergeLEDColor(current[0], d.led, color)
	if err != nil {
		return err
	}
	if next == current[0] {
		return nil
	}
	written, err := d.image.Write(d.offset, []byte{next})
	if err != nil {
		return fmt.Errorf("write RevPiLED: %w", err)
	}
	if written != 1 {
		return fmt.Errorf("write RevPiLED: %w", io.ErrShortWrite)
	}
	return nil
}

func (d *ledDevice) Close() error { return d.image.Close() }
